types.javadoc:
Bins continuous data into intervals using {@code QUANTILE}, {@code UNIFORM}, or {@code KMEANS}
strategies and outputs {@code ORDINAL} or {@code ONEHOT_DENSE} encodings, matching
{@code sklearn.preprocessing.KBinsDiscretizer}.

doc.example:
Matrix x = Matrix.fromRows(new double[][] {
        {0.0, 10.0}, {0.5, 12.0}, {1.0, 14.0},
        {2.0, 16.0}, {4.0, 18.0}, {8.0, 20.0}
});

KBinsDiscretizer discretizer = KBinsDiscretizer.builder()
        .nBins(3)
        .strategy(KBinsDiscretizer.Strategy.QUANTILE)
        .encode(KBinsDiscretizer.Encode.ORDINAL)
        .build()
        .fit(x);

Matrix binned = discretizer.transform(x);
Matrix restored = discretizer.inverseTransform(binned);
double[][] edges = discretizer.binEdges();

Matrix x = Matrix.fromRows(new double[][] {
        {0.0, 1.0}, {1.0, 0.0}, {1.0, 1.0}, {2.0, 2.0},
        {2.0, 3.0}, {3.0, 2.0}, {3.0, 3.0}, {4.0, 4.0}
});
double[] y = {0.0, 0.0, 1.0, 1.0, 1.0, 0.0, 1.0, 0.0};

KFold kfold = new KFold(4);
List<DataSplit.Fold> folds = kfold.split(x, y);

DataSplit.Fold first = folds.get(0);
Matrix trainX = first.trainFeatures();
Matrix testX = first.testFeatures();
int count = kfold.folds();
boolean shuffled = kfold.shuffle();

Matrix features = Matrix.fromRows(new double[][] {
    {0.0, 0.0}, {0.4, 0.2}, {0.1, 0.5},
    {9.6, 9.8}, {10.0, 10.2}, {9.4, 9.9}
});
KMeans kmeans = KMeans.builder()
        .clusters(2)
        .restarts(4)
        .maxIterations(200)
        .seed(7L)
        .build()
        .fit(features);
double[] assignment = kmeans.predict(features);
double[] distance = kmeans.transform(features);
Matrix centers = kmeans.centroids();
double inertia = kmeans.inertia();

